/*
  Google Assistant Home Automation
  ESP32-WROOM-32 + 4-Channel Relay
  ACTIVE-HIGH
  Adafruit IO MQTT over TLS

  Relay inputs:
    IN1 -> GPIO25
    IN2 -> GPIO26
    IN3 -> GPIO27
    IN4 -> GPIO33

  ACTIVE-HIGH:
    HIGH = ON
    LOW  = OFF

  MQTT:
    Adafruit IO secure MQTT
    Port 8883 (TLS)

  IMPORTANT:
    Replace AIO_KEY with your current Adafruit IO key.
*/

#include <WiFi.h>
#include <WiFiClientSecure.h>
#include "Adafruit_MQTT.h"
#include "Adafruit_MQTT_Client.h"

// =====================================================
// RELAY PINS
// =====================================================

#define Relay1 25
#define Relay2 26
#define Relay3 27
#define Relay4 33

// =====================================================
// WIFI SETTINGS
// =====================================================

#define WLAN_SSID "1212"
#define WLAN_PASS "999999999"

// =====================================================
// ADAFRUIT IO SETTINGS
// =====================================================

#define AIO_SERVER "io.adafruit.com"
#define AIO_SERVERPORT 8883

#define AIO_USERNAME "elecmake2"

// Replace with your NEW Adafruit IO key.
#define AIO_KEY "REPLACE_WITH_YOUR_NEW_ADAFRUIT_IO_KEY"

// =====================================================
// MQTT CLIENT
// =====================================================

WiFiClientSecure client;

Adafruit_MQTT_Client mqtt(
  &client,
  AIO_SERVER,
  AIO_SERVERPORT,
  AIO_USERNAME,
  AIO_KEY
);

// =====================================================
// ADAFRUIT IO FEEDS
// =====================================================

Adafruit_MQTT_Subscribe Light1 =
  Adafruit_MQTT_Subscribe(
    &mqtt,
    AIO_USERNAME "/feeds/Relay1"
  );

Adafruit_MQTT_Subscribe Light2 =
  Adafruit_MQTT_Subscribe(
    &mqtt,
    AIO_USERNAME "/feeds/Relay2"
  );

Adafruit_MQTT_Subscribe Light3 =
  Adafruit_MQTT_Subscribe(
    &mqtt,
    AIO_USERNAME "/feeds/Relay3"
  );

Adafruit_MQTT_Subscribe Light4 =
  Adafruit_MQTT_Subscribe(
    &mqtt,
    AIO_USERNAME "/feeds/Relay4"
  );

// =====================================================
// FUNCTION DECLARATIONS
// =====================================================

void allRelaysOff();
void connectWiFi();
bool connectMQTT();
void processRelay(
  Adafruit_MQTT_Subscribe *subscription,
  int relayPin,
  const char *relayName,
  uint8_t *payload
);

// =====================================================
// SETUP
// =====================================================

void setup() {

  Serial.begin(115200);
  delay(500);

  Serial.println();
  Serial.println("==========================================");
  Serial.println(" ESP32 HOME AUTOMATION");
  Serial.println(" ACTIVE-HIGH RELAY");
  Serial.println(" ADAFRUIT IO MQTT TLS");
  Serial.println("==========================================");

  // ---------------------------------------------------
  // Configure relay pins.
  // ACTIVE-HIGH => LOW means OFF.
  // ---------------------------------------------------

  pinMode(Relay1, OUTPUT);
  pinMode(Relay2, OUTPUT);
  pinMode(Relay3, OUTPUT);
  pinMode(Relay4, OUTPUT);

  allRelaysOff();

  // ---------------------------------------------------
  // Connect WiFi
  // ---------------------------------------------------

  connectWiFi();

  // ---------------------------------------------------
  // TLS configuration
  // ---------------------------------------------------
  // This uses TLS encryption on port 8883.
  //
  // setInsecure() means the connection is encrypted,
  // but the server certificate is not verified.
  //
  // A CA certificate can be installed later for
  // full certificate validation.
  // ---------------------------------------------------

  client.setInsecure();

  // ---------------------------------------------------
  // Subscribe to Adafruit IO feeds
  // ---------------------------------------------------

  mqtt.subscribe(&Light1);
  mqtt.subscribe(&Light2);
  mqtt.subscribe(&Light3);
  mqtt.subscribe(&Light4);

  Serial.println("MQTT feeds subscribed.");
  Serial.println("System ready.");
}

// =====================================================
// LOOP
// =====================================================

void loop() {

  // ---------------------------------------------------
  // Keep WiFi connected
  // ---------------------------------------------------

  if (WiFi.status() != WL_CONNECTED) {

    Serial.println("WiFi disconnected.");

    allRelaysOff();

    connectWiFi();
  }

  // ---------------------------------------------------
  // Keep MQTT connected
  // ---------------------------------------------------

  if (!connectMQTT()) {

    delay(2000);

    return;
  }

  // ---------------------------------------------------
  // Read MQTT messages
  // ---------------------------------------------------

  Adafruit_MQTT_Subscribe *subscription;

  while ((subscription = mqtt.readSubscription(1000))) {

    if (subscription == &Light1) {

      processRelay(
        &Light1,
        Relay1,
        "Relay 1",
        Light1.lastread
      );
    }

    if (subscription == &Light2) {

      processRelay(
        &Light2,
        Relay2,
        "Relay 2",
        Light2.lastread
      );
    }

    if (subscription == &Light3) {

      processRelay(
        &Light3,
        Relay3,
        "Relay 3",
        Light3.lastread
      );
    }

    if (subscription == &Light4) {

      processRelay(
        &Light4,
        Relay4,
        "Relay 4",
        Light4.lastread
      );
    }
  }

  // ---------------------------------------------------
  // Keep MQTT connection alive.
  // ---------------------------------------------------

  if (!mqtt.ping()) {

    Serial.println("MQTT ping failed.");
    mqtt.disconnect();
  }

  delay(10);
}

// =====================================================
// PROCESS RELAY COMMAND
// =====================================================

void processRelay(
  Adafruit_MQTT_Subscribe *subscription,
  int relayPin,
  const char *relayName,
  uint8_t *payload
) {

  (void)subscription;

  int state = atoi((char *)payload);

  // Only accept 0 and 1.
  if (state != 0 && state != 1) {

    Serial.print(relayName);
    Serial.println(" -> invalid command");

    return;
  }

  // ACTIVE-HIGH:
  // 1 -> HIGH -> ON
  // 0 -> LOW  -> OFF

  digitalWrite(
    relayPin,
    state ? HIGH : LOW
  );

  Serial.print(relayName);
  Serial.print(" -> ");
  Serial.println(state ? "ON" : "OFF");
}

// =====================================================
// TURN ALL RELAYS OFF
// =====================================================

void allRelaysOff() {

  // ACTIVE-HIGH:
  // LOW = OFF

  digitalWrite(Relay1, LOW);
  digitalWrite(Relay2, LOW);
  digitalWrite(Relay3, LOW);
  digitalWrite(Relay4, LOW);
}

// =====================================================
// WIFI CONNECTION
// =====================================================

void connectWiFi() {

  Serial.println();
  Serial.print("Connecting to WiFi: ");
  Serial.println(WLAN_SSID);

  WiFi.mode(WIFI_STA);
  WiFi.begin(WLAN_SSID, WLAN_PASS);

  int attempts = 0;

  while (
    WiFi.status() != WL_CONNECTED &&
    attempts < 30
  ) {

    delay(500);

    Serial.print(".");

    attempts++;
  }

  Serial.println();

  if (WiFi.status() == WL_CONNECTED) {

    Serial.println("WiFi connected.");

    Serial.print("IP address: ");
    Serial.println(WiFi.localIP());

    Serial.print("RSSI: ");
    Serial.print(WiFi.RSSI());
    Serial.println(" dBm");

  } else {

    Serial.println(
      "WiFi connection failed. Will retry later."
    );
  }
}

// =====================================================
// MQTT CONNECTION
// =====================================================

bool connectMQTT() {

  if (mqtt.connected()) {
    return true;
  }

  Serial.println();
  Serial.print("Connecting to Adafruit IO MQTT TLS...");

  // Up to 5 attempts per cycle.
  for (uint8_t attempt = 1; attempt <= 5; attempt++) {

    int8_t ret = mqtt.connect();

    if (ret == 0) {

      Serial.println(" connected!");

      return true;
    }

    Serial.println();

    Serial.print("MQTT error: ");
    Serial.println(
      mqtt.connectErrorString(ret)
    );

    mqtt.disconnect();

    delay(2000);

    Serial.print("Retry ");
    Serial.print(attempt);
    Serial.println("/5");
  }

  Serial.println(
    "MQTT unavailable. Will retry later."
  );

  return false;
}
